CREATE TABLE attendance_sessions (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, class_id text NOT NULL, day date NOT NULL, session_key text NOT NULL DEFAULT 'daily', created_by text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted')), revision integer NOT NULL DEFAULT 1, submitted_at timestamptz, UNIQUE(org_id,id), UNIQUE(org_id,class_id,day,session_key), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,class_id) REFERENCES classes(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id));
CREATE TABLE attendance_entries (org_id text NOT NULL, session_id text NOT NULL, student_id text NOT NULL, status text NOT NULL CHECK(status IN ('present','absent','late','excused')), PRIMARY KEY(org_id,session_id,student_id), FOREIGN KEY(org_id,session_id) REFERENCES attendance_sessions(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id));
CREATE TABLE attendance_revisions (id text PRIMARY KEY, org_id text NOT NULL, session_id text NOT NULL, actor_id text NOT NULL, revision integer NOT NULL, reason text NOT NULL, before_entries jsonb NOT NULL, after_entries jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,revision), FOREIGN KEY(org_id,session_id) REFERENCES attendance_sessions(org_id,id), FOREIGN KEY(org_id,actor_id) REFERENCES users(org_id,id));
CREATE TABLE homework (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, class_id text NOT NULL, subject_id text NOT NULL, created_by text NOT NULL, title text NOT NULL, instructions text NOT NULL, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','published','archived')), scheduled_at timestamptz, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,class_id) REFERENCES classes(org_id,id), FOREIGN KEY(org_id,subject_id) REFERENCES subjects(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id));
CREATE TABLE homework_files (org_id text NOT NULL, homework_id text NOT NULL, file_id text NOT NULL, PRIMARY KEY(org_id,homework_id,file_id), FOREIGN KEY(org_id,homework_id) REFERENCES homework(org_id,id), FOREIGN KEY(org_id,file_id) REFERENCES file_assets(org_id,id));
CREATE TABLE submissions (id text PRIMARY KEY, org_id text NOT NULL, homework_id text NOT NULL, student_id text NOT NULL, submitted_by text NOT NULL, text text NOT NULL, file_id text, revision integer NOT NULL DEFAULT 1, submitted_at timestamptz NOT NULL DEFAULT now(), feedback text, reviewed_by text, reviewed_at timestamptz, UNIQUE(org_id,id), UNIQUE(org_id,homework_id,student_id), FOREIGN KEY(org_id,homework_id) REFERENCES homework(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id), FOREIGN KEY(org_id,submitted_by) REFERENCES users(org_id,id), FOREIGN KEY(org_id,file_id) REFERENCES file_assets(org_id,id), FOREIGN KEY(org_id,reviewed_by) REFERENCES users(org_id,id));
CREATE TABLE leave_requests (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, student_id text, created_by text NOT NULL, kind text NOT NULL, starts date NOT NULL, ends date NOT NULL CHECK(ends>=starts), reason text NOT NULL, status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','approved','rejected','changes_requested')), revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id));
